  std::any parseWsOHLCV(std::any ohlcv, std::any market = std::any{}) override {
    //
    //    {
    //        "symbol": "BTC_USDT",
    //        "amount": "840.7240416",
    //        "high": "24832.35",
    //        "quantity": "0.033856",
    //        "tradeCount": 1,
    //        "low": "24832.35",
    //        "closeTime": 1676942519999,
    //        "startTime": 1676942460000,
    //        "close": "24832.35",
    //        "open": "24832.35",
    //        "ts": 1676942492072
    //    }
    //
    return ccxt::list{this->safeInteger(ohlcv, std::string("startTime")),
                      this->safeNumber(ohlcv, std::string("open")),
                      this->safeNumber(ohlcv, std::string("high")),
                      this->safeNumber(ohlcv, std::string("low")),
                      this->safeNumber(ohlcv, std::string("close")),
                      this->safeNumber(ohlcv, std::string("quantity"))};
  }

  virtual std::any handleOHLCV(std::any client, std::any message) {
    //
    //    {
    //        "channel": "candles_minute_1",
    //        "data": [
    //            {
    //                "symbol": "BTC_USDT",
    //                "amount": "840.7240416",
    //                "high": "24832.35",
    //                "quantity": "0.033856",
    //                "tradeCount": 1,
    //                "low": "24832.35",
    //                "closeTime": 1676942519999,
    //                "startTime": 1676942460000,
    //                "close": "24832.35",
    //                "open": "24832.35",
    //                "ts": 1676942492072
    //            }
    //        ]
    //    }
    //
    std::any data = this->safeValue(message, std::string("data"));
    data = this->safeValue(data, 0);
    std::any channel = this->safeString(message, std::string("channel"));
    std::any marketId = this->safeString(data, std::string("symbol"));
    std::any symbol = this->safeSymbol(marketId);
    std::any market = this->safeMarket(symbol);
    std::any timeframes =
        this->safeValue(this->options, std::string("timeframes"), ccxt::dict{});
    std::any timeframe = this->findTimeframe(channel, timeframes);
    std::any messageHash = add(add(channel, std::string("::")), symbol);
    std::any parsed = this->parseWsOHLCV(data, market);
    ::setValue(this->ohlcvs, symbol,
               this->safeValue(this->ohlcvs, symbol, ccxt::dict{}));
    std::any stored =
        (isTrue((isEqual(timeframe, std::any{})))
             ? std::any(std::any{})
             : std::any(this->safeValue(this->safeValue(this->ohlcvs, symbol),
                                        timeframe)));
    if (isTrue(!isEqual(symbol, std::any{}))) {
      if (isTrue(isEqual(stored, std::any{}))) {
        std::any limit =
            this->safeInteger(this->options, std::string("OHLCVLimit"), 1000);
        stored = ccxt::ws::ArrayCacheByTimestamp(limit);
        if (isTrue(isTrue(!isEqual(symbol, std::any{})) &&
                   isTrue(!isEqual(timeframe, std::any{})))) {
          ::setValue(::getValue(this->ohlcvs, symbol), timeframe, stored);
        }
      }
      ::wsAppend(stored, parsed);
      this->resolve(stored, messageHash);
    }
    return message;
  }

  virtual std::any handleTrade(std::any client, std::any message) {
    //
    //    {
    //        "channel": "trades",
    //        "data": [
    //            {
    //                "symbol": "BTC_USDT",
    //                "amount": "13.41634893",
    //                "quantity": "0.000537",
    //                "takerSide": "buy",
    //                "createTime": 1676950548834,
    //                "price": "24983.89",
    //                "id": "62486976",
    //                "ts": 1676950548839
    //            }
    //        ]
    //    }
    //
    std::any data = this->safeValue(message, std::string("data"), ccxt::list{});
    for (std::any i = 0; isLessThan(i, getArrayLength(data));
         postFixIncrement(i)) {
      std::any item = ::getValue(data, i);
      std::any marketId = this->safeString(item, std::string("symbol"));
      if (isTrue(!isEqual(marketId, std::any{}))) {
        std::any trade = this->parseWsTrade(item);
        std::any symbol = ::getValue(trade, std::string("symbol"));
        std::any type = std::string("trades");
        std::any messageHash = add(add(type, std::string("::")), symbol);
        std::any tradesArray =
            (isTrue((isEqual(symbol, std::any{})))
                 ? std::any(std::any{})
                 : std::any(this->safeValue(this->trades, symbol)));
        if (isTrue(isEqual(tradesArray, std::any{}))) {
          std::any tradesLimit = this->safeInteger(
              this->options, std::string("tradesLimit"), 1000);
          tradesArray = ccxt::ws::ArrayCache(tradesLimit);
          if (isTrue(!isEqual(symbol, std::any{}))) {
            ::setValue(this->trades, symbol, tradesArray);
          }
        }
        ::wsAppend(tradesArray, trade);
        this->resolve(tradesArray, messageHash);
      }
    }
    return message;
  }

  std::any parseWsTrade(std::any trade, std::any market = std::any{}) override {
    //
    // handleTrade
    //
    //    {
    //        "symbol": "BTC_USDT",
    //        "amount": "13.41634893",
    //        "quantity": "0.000537",
    //        "takerSide": "buy",
    //        "createTime": 1676950548834,
    //        "price": "24983.89",
    //        "id": "62486976",
    //        "ts": 1676950548839
    //    }
    //
    // private trade
    //    {
    //        "orderId":"186250258089635840",
    //        "tradeId":"62036513",
    //        "clientOrderId":"",
    //        "accountType":"SPOT",
    //        "eventType":"trade",
    //        "symbol":"ADA_USDT",
    //        "side":"SELL",
    //        "type":"MARKET",
    //        "price":"0",
    //        "quantity":"3",
    //        "state":"FILLED",
    //        "createTime":1685371921891,
    //        "tradeTime":1685371921908,
    //        "tradePrice":"0.37694",
    //        "tradeQty":"3",
    //        "feeCurrency":"USDT",
    //        "tradeFee":"0.00226164",
    //        "tradeAmount":"1.13082",
    //        "filledQuantity":"3",
    //        "filledAmount":"1.13082",
    //        "ts":1685371921945,
    //        "source":"WEB",
    //        "orderAmount":"0",
    //        "matchRole":"TAKER"
    //     }
    //
    std::any marketId = this->safeString(trade, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    std::any timestamp = this->safeInteger(trade, std::string("createTime"));
    std::any takerMaker = this->safeStringLower2(
        trade, std::string("matchRole"), std::string("taker"));
    return this->safeTrade(
        ccxt::dict{
            {std::string("info"), trade},
            {std::string("id"), this->safeString2(trade, std::string("id"),
                                                  std::string("tradeId"))},
            {std::string("symbol"),
             this->safeString(market, std::string("symbol"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("order"),
             this->safeString(trade, std::string("orderId"))},
            {std::string("type"),
             this->safeStringLower(trade, std::string("type"))},
            {std::string("side"),
             this->safeStringLower2(trade, std::string("takerSide"),
                                    std::string("side"))},
            {std::string("takerOrMaker"), takerMaker},
            {std::string("price"),
             this->omitZero(this->safeString2(trade, std::string("tradePrice"),
                                              std::string("price")))},
            {std::string("amount"), this->omitZero(this->safeString2(
                                        trade, std::string("filledQuantity"),
                                        std::string("quantity")))},
            {std::string("cost"),
             this->safeString2(trade, std::string("amount"),
                               std::string("filledAmount"))},
            {std::string("fee"),
             ccxt::dict{
                 {std::string("rate"), std::any{}},
                 {std::string("cost"),
                  this->safeString(trade, std::string("tradeFee"))},
                 {std::string("currency"),
                  this->safeString(trade, std::string("feeCurrency"))},
             }},
        },
        market);
  }

  virtual std::any parseStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("NEW"), std::string("open")},
        {std::string("PARTIALLY_FILLED"), std::string("open")},
        {std::string("FILLED"), std::string("closed")},
        {std::string("PENDING_CANCEL"), std::string("open")},
        {std::string("PARTIALLY_CANCELED"), std::string("open")},
        {std::string("CANCELED"), std::string("canceled")},
    };
    return this->safeString(statuses, status, status);
  }

